// Downloads the workspace OpenAPI document (generated by Monospace from the live schema of
// BOTH databases) and generates a typed TypeScript client from it.
import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
import { WS, c, login, request } from './lib.mjs'

const token = await login()
const doc = await request(`/${WS}/openapi`, { token })
writeFileSync(new URL('../app/openapi.json', import.meta.url), JSON.stringify(doc, null, 2))
console.log(`${c.green('✓')} app/openapi.json: ${Object.keys(doc.paths ?? {}).length} paths`)
execFileSync('npx', ['monospace', 'sdk', 'generate', '--config', 'monospace.config.ts', '--no-input'], {
  cwd: new URL('../app/', import.meta.url),
  stdio: 'inherit',
})
console.log(`${c.green('✓')} typed client: app/generated/monospace/index.ts`)
